#!/usr/bin/env bash
# batch_p05_session_lifecycle.sh
#
# P0.5 (G6/G7/G8, disasters #11 + multi-instance safety): session lifecycle
# state machine - reconnect/DisconnectReason handling with exponential
# backoff, Redis lease + fencing for multi-instance coordination (only one
# gateway instance ever runs a given session), staged rehydrate boot bounded
# by REHYDRATE_CONCURRENCY, a real-measured MAX_SESSIONS capacity cap, and
# human-takeover-signal detection (a merchant typing directly on their own
# phone must never be treated as a bot echo or forwarded to Django as an
# ordinary customer message).
#
# Also fixes a real, severe bug found while building this phase's own tests
# (see docs/P0_FINDINGS.md F8): every session's outbound send-queue worker
# used to share ONE Redis connection for its blocking BLMOVE poll loop -
# with several sessions running, this starves every other Redis command
# (lease ops, WAL appends) queued behind it, eventually causing real command
# timeouts. Each outbound worker now gets its own dedicated connection.
#
# This script only WRITES files and RUNS verification (hunt_gate + the full
# real-Redis test suite, including the two new P0.5 acceptance tests: staged
# rehydrate concurrency, and a real dual-process kill -9 lease-failover
# test). It does NOT run `git add`/`git commit` - review the diff yourself,
# then commit separately (a dedicated batch_p05_commit.sh will follow once
# you confirm this one is clean).
#
# getSessionStatus / mapConnectionStatus's existing external contract
# (consumed by Django) is UNCHANGED - a regression guard test proves this
# explicitly. All new P0.5 state is exposed only via the new, additive
# GET /sessions/:id/health endpoint.
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -euo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
if [ ! -d "$REPO_ROOT/gateway" ]; then
  echo "ERROR: $REPO_ROOT/gateway not found. Run this script from a machine where the repo lives at $REPO_ROOT, or edit REPO_ROOT at the top of this script." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "=== [0/6] Pre-flight: repo root = $REPO_ROOT ==="
git rev-parse --is-inside-work-tree >/dev/null 2>&1 && echo "  git repo: OK" || { echo "ERROR: not a git repository" >&2; exit 1; }

echo ""
echo "=== [1/6] Writing P0.5 files (base64-embedded, decoded in place) ==="

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

