echo ""
echo "=== [2/6] Sanity: new P0.5 env vars documented ==="
grep -n "LEASE_TTL_MS" gateway/.env.example || { echo "ERROR: P0.5 env vars missing from .env.example" >&2; exit 1; }

echo ""
echo "=== [3/6] Syntax-check every new/modified JS file ==="
for f in \
  gateway/src/config.js \
  gateway/src/lease.js \
  gateway/src/sessions.js \
  gateway/src/index.js \
  gateway/src/forwarder.js \
  gateway/src/driver/waDriver.js \
  gateway/src/ingest/spool.js \
  gateway/src/__tests__/forwarder.test.js \
  gateway/src/__tests__/webhook.test.js \
  gateway/src/__tests__/lease.test.js \
  gateway/src/__tests__/session_state.test.js \
  gateway/src/__tests__/human_takeover.test.js \
  gateway/src/__tests__/rehydrate_staging.test.js \
  gateway/src/__tests__/dual_instance_chaos.test.js \
  gateway/src/__tests__/_dual_instance_chaos_child.mjs \
; do
  node --check "$f" && echo "  OK: $f"
done

echo ""
echo "=== [4/6] hunt_gate (static discipline check) ==="
if command -v node >/dev/null 2>&1 && [ -f scripts/hunt_gate.mjs ]; then
  node scripts/hunt_gate.mjs || echo "  (hunt_gate reported violations above - review them; prior phases showed only non-fatal scratch-script violations, but check this run's output yourself)"
else
  echo "  SKIPPED: node or scripts/hunt_gate.mjs not found on PATH/repo - run it manually and review before committing."
fi

echo ""
echo "=== [5/6] Full real-Redis test suite (all P0.2-P0.5 tests together), via the live redis-durable stack ==="
echo "    (No standalone redis-server binary exists on this VPS - Redis only runs via Docker here, same as every other"
echo "     real-Redis suite in this project.)"
echo ""
echo "    All P0.5 test keys/sessions use randomized ids (crypto.randomUUID()) so nothing collides with real session"
echo "    data, and nothing is flushed - same precedent as every earlier phase's real-Redis suite."
echo ""

if ! command -v docker >/dev/null 2>&1; then
  echo "ERROR: docker not found - cannot run the real-Redis test suite. Install docker or run the tests manually against a real redis-durable." >&2
  exit 1
fi

DC="docker compose"
$DC version >/dev/null 2>&1 || DC="docker-compose"

echo "--- running full suite (src/__tests__/*.test.js) ---"
$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test "src/__tests__/*.test.js"

echo ""
echo "--- running the P0.5 staged-rehydrate acceptance test again on its own, for a clean, isolated result ---"
echo "    (spec: booting N registered sessions -> never more than REHYDRATE_CONCURRENCY connect simultaneously)"
$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test src/__tests__/rehydrate_staging.test.js

echo ""
echo "--- running the P0.5 dual-instance lease/fencing chaos test again on its own, for a clean, isolated result ---"
echo "    (spec: two real gateway instances on the SAME session -> only one runs it; kill -9 the carrier -> the"
echo "     survivor takes over once the lease TTL expires, and the old writer is rejected by fencing)"
$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test src/__tests__/dual_instance_chaos.test.js

echo ""
echo "=== [6/6] Review: git status / diff --stat (NO commit performed by this script) ==="
git status --short
echo ""
git diff --stat -- gateway/src gateway/.env.example docs/P0_DEVIATIONS.md docs/P0_FINDINGS.md || true

echo ""
echo "=== Done. Nothing was committed. Review the diff above, then commit yourself when satisfied. ==="
